# Generated by build.py from recipe.yml for recipe ldap-bind-with-ntlm. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/ldap
cat > site/.surl/ldap/directory.ldif <<'EOF'
dn: dc=example,dc=com
objectClass: domain
dc: example

dn: cn=alice,dc=example,dc=com
objectClass: person
cn: alice
mail: alice@example.com
EOF
surl --directory site --auth ntlm -u alice:s3cret ldap://127.0.0.1:8080/ &
sleep 1
curl --ntlm -u alice:s3cret "ldap://127.0.0.1:8080/dc=example,dc=com?mail?sub?(cn=alice)"
kill $(jobs -p)
